export async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {
  if (!(await isIssueLive(orgId, issue.id))) {
    await removeFromIndex(orgId, "issue", issue.id);
    return;
  }
  const current = (await issueRepo.findIssueById(orgId, issue.id)) ?? issue;
  await searchRepo.upsertSearchDocument(
    orgId,
    "issue",
    current.id,
    [current.title, current.description ?? ""].join("\\n"),
    current.projectId,
  );
}

export async function indexComment(
  orgId: OrgId,
  comment: Comment,
): Promise<void> {
  const current = await commentRepo.findCommentById(orgId, comment.id);
  if (
    !current ||
    current.archivedAt !== null ||
    !(await isIssueLive(orgId, current.issueId))
  ) {
    await removeFromIndex(orgId, "comment", comment.id);
    return;
  }
  await searchRepo.upsertSearchDocument(
    orgId,
    "comment",
    current.id,
    current.body,
    null,
  );
}

export async function indexProject(
  orgId: OrgId,
  project: Project,
): Promise<void> {
  const current = await projectRepo.findProjectById(orgId, project.id);
  if (!current || current.archivedAt !== null) {
    await removeFromIndex(orgId, "project", project.id);
    return;
  }
  await searchRepo.upsertSearchDocument(
    orgId,
    "project",
    current.id,
    [current.name, current.description ?? ""].join("\\n"),
    current.id,
  );
}

/** Every comment on an issue, archived ones included, across all pages. */
export async function listAllComments(
  orgId: OrgId,
  issueId: Issue["id"],
): Promise<Comment[]> {
  const out: Comment[] = [];
  let cursor: string | null = null;
  do {
    const page = await commentRepo.listComments({
      orgId,
      issueId,
      includeArchived: true,
      limit: 100,
      cursor,
    });
    out.push(...page.items);
    cursor = page.nextCursor;
  } while (cursor);
  return out;
}

/** Every issue in a project (or the whole org), archived ones included. */
export async function listAllIssues(
  orgId: OrgId,
  projectId?: Project["id"],
): Promise<Issue[]> {
  const out: Issue[] = [];
  let cursor: string | null = null;
  do {
    const page = await issueRepo.listIssues({
      orgId,
      ...(projectId === undefined ? {} : { projectId }),
      includeArchived: true,
      limit: 100,
      cursor,
    });
    out.push(...page.items);
    cursor = page.nextCursor;
  } while (cursor);
  return out;
}

/** Re-evaluates an issue and all of its comments against the liveness rule. */
async function reindexIssueTree(orgId: OrgId, issue: Issue): Promise<void> {
  await indexIssue(orgId, issue);
  for (const comment of await listAllComments(orgId, issue.id)) {
    await indexComment(orgId, comment);
  }
}

/** Re-evaluates a project, its issues and their comments. */
async function reindexProjectTree(
  orgId: OrgId,
  projectId: Project["id"],
): Promise<void> {
  const project = await projectRepo.findProjectById(orgId, projectId);
  if (project) await indexProject(orgId, project);
  else await removeFromIndex(orgId, "project", projectId);
  for (const issue of await listAllIssues(orgId, projectId)) {
    await reindexIssueTree(orgId, issue);
  }
}

